mapper.select:
SELECT a.id, CASE a.use_type WHEN 'READ' THEN '查阅档案申请' WHEN 'BORROW' THEN '借用档案申请' WHEN 'HANDOVER' THEN '移交档案申请' ELSE '档案访问申请' END AS title, a.id AS resource_id, NULL AS employee_id, a.status, NULL AS due_at, a.created_at FROM archive_access_application a WHERE a.status = 'PENDING_APPROVAL' AND #{allowHrApproval} = TRUE AND ( 1 = 1 a.department_id = #{departmentId}
EXISTS (SELECT 1 FROM sys_user u WHERE u.id = a.applicant_id AND u.employee_id = #{employeeId})
1 = 0 ) ORDER BY a.created_at DESC, a.id DESC LIMIT #{limit}

SELECT u.id, CONCAT('档案归还 · ', a.application_no) AS title, a.id AS resource_id, NULL AS employee_id, a.status, a.due_at, u.used_at AS created_at FROM archive_use_record u JOIN archive_access_application a ON a.id = u.application_id WHERE u.id = (SELECT MAX(u2.id) FROM archive_use_record u2 WHERE u2.application_id = a.id) AND ((a.status = 'IN_USE' AND u.returned_at IS NULL AND a.due_at <= #{dueSoonUntil}) OR a.status = 'ABNORMAL') AND ( 1 = 1 a.department_id = #{departmentId}
EXISTS (SELECT 1 FROM sys_user u2 WHERE u2.id = a.applicant_id AND u2.employee_id = #{employeeId})
1 = 0 ) ORDER BY a.due_at ASC, u.used_at DESC, u.id DESC LIMIT #{limit}
